Req high_precision_machining_requirements
requirement HP:
  Id: "001";
  Text: "High-precision machining requirements";
end;
requirement P1:
  Id: "002";
  Text: "Micron-level positioning capability to ensure accuracy of workpiece machining positions";
end;
requirement P2:
  Id: "003";
  Text: "Minimal spindle runout to guarantee machined surface finish and dimensional accuracy";
end;
requirement P3:
  Id: "004";
  Text: "Automatic temperature compensation to prevent thermal deformation from affecting machining accuracy";
end;
requirement P4:
  Id: "005";
  Text: "Vibration reduction during machining to improve surface quality and tool life";
end;

requirement MCC:
  Id: "006";
  Text: "Metal cutting control requirements";
end;
requirement C1:
  Id: "007";
  Text: "Programmable adjustment of rotational speed, feed rate, cutting depth, etc., with optimization recommendation function";
end;
requirement C2:
  Id: "008";
  Text: "Automatic multi-tool switching, recording of tool usage status and life, with wear detection and alarm functions";
end;
requirement C3:
  Id: "009";
  Text: "Real-time monitoring of cutting force, power consumption, etc., with automatic adjustment or shutdown protection under abnormal conditions";
end;
requirement C4:
  Id: "010";
  Text: "Automatic control of coolant on/off and flow rate based on machining status to improve machining efficiency and tool life";
end;

requirement PM:
  Id: "011";
  Text: "Part processing workflow management requirements";
end;
requirement M1:
  Id: "012";
  Text: "Support for G-code import, editing, and storage, with program simulation and error checking functions";
end;
requirement M2:
  Id: "013";
  Text: "Assist in generating optimal machining paths to reduce idle travel time and improve machining efficiency";
end;
requirement M3:
  Id: "014";
  Text: "Support for queuing and execution of multiple machining tasks, with priority setting and interrupt recovery mechanisms";
end;
requirement M4:
  Id: "015";
  Text: "Provide an intuitive operation interface displaying current machining status, alarm information, and operational guidance";
end;
requirement M5:
  Id: "016";
  Text: "Record data for each machining operation (e.g., time, parameters, tool usage) for subsequent analysis and quality traceability";
end;

traceability:
  compose(P1, HP);
  compose(P2, HP);
  compose(P3, HP);
  compose(P4, HP);

  compose(C1, MCC);
  compose(C2, MCC);
  compose(C3, MCC);
  compose(C4, MCC);

  compose(M1, PM);
  compose(M2, PM);
  compose(M3, PM);
  compose(M4, PM);
  compose(M5, PM);
end;

actor:
  operator;
  technician;
  manager;
end;
system CNC_processing_center
