    interact(operator,debugProgram);
    interact(technician,inspectEquipment);
    interact(technician,diagnoseFix);
    interact(technician,replaceConsumables);
    interact(manager,manageProduction);
    interact(manager,performanceReport);
    interact(manager,costControl);
end;

discrete ControlAndProgrammingSystem
port:
    event input real StartSystem;
    event input real UploadProgram;
    event input real ConfirmExecution;
    event input real ProgramFinished;
    event input real ReloadProgram;
    event input real SystemFault;
    event output real ProgramLoaded;
    event output real ExecutionStarted;
    event output real ExecutionFinished;
    event output real FaultDetected;
state:
    initial state State1
    when entry() then
        statehold(1);
    end;
    when receive(StartSystem) then
        transition(State1);
    end;
    when receive(UploadProgram) then
        transition(State2);
        out
            send(ProgramLoaded, 1);
    end;
    when receive(ConfirmExecution) then
        transition(State3);
        out
            send(ExecutionStarted, 1);
    end;
    when receive(ProgramFinished) then
        transition(State4);
        out
            send(ExecutionFinished, 1);
    end;
    when receive(ReloadProgram) then
        transition(State1);
    end;
    when receive(SystemFault) then
        transition(State5);
        out
            send(FaultDetected, 1);
    end;
end;
state State2
    when entry() then
        statehold(1);
    end;
    when receive(ConfirmExecution) then
        transition(State3);
        out
            send(ExecutionStarted, 1);
    end;
    when receive(SystemFault) then
        transition(State5);
        out
            send(FaultDetected, 1);
    end;
end;
state State3
    when entry() then
        statehold(1);
    end;
    when receive(ProgramFinished) then
        transition(State4);
        out
            send(ExecutionFinished, 1);
    end;
    when receive(SystemFault) then
        transition(State5);
        out
            send(FaultDetected, 1);
    end;
end;
state State4
    when entry() then
        statehold(1);
    end;
    when receive(ReloadProgram) then
        transition(State1);
    end;
    when timeover() then
        transition(State1);
    end;
end;
state State5
    when entry() then
        statehold(1);
    end;
    when receive(SystemFault) then
        transition(State5);
        out
            send(FaultDetected, 1);
    end;
    when receive(StartSystem) then
        transition(State1);
    end;
end;

