couple System
import architectureModels.ControlAndProgrammingSystem as CPS;
import architectureModels.MechanicalTransmissionSystem as MTS;
import architectureModels.ToolManagementSystem as TMS;
import architectureModels.CoolingAndLubricationSystem as CLS;
import architectureModels.MonitoringAndDiagnosisSystem as MDS;

part:
    CPS cpsInstance;
    MTS mtsInstance;
    TMS tmsInstance;
    CLS clsInstance;
    MDS mdsInstance;

connection:
    connect(cpsInstance.ProgramLoaded, mtsInstance.ReadyForCommands);
    connect(cpsInstance.ExecutionStarted, mtsInstance.OperationInProgress);
    connect(cpsInstance.ExecutionFinished, mtsInstance.ReadyForCommands);
    connect(cpsInstance.FaultDetected, mdsInstance.AbnormalDetected);
    connect(mtsInstance.ReadyForCommands, tmsInstance.Idle);
    connect(mtsInstance.OperationInProgress, tmsInstance.ToolChangeRequest);
    connect(tmsInstance.ToolChangeInProgress, mtsInstance.OperationInProgress);
    connect(tmsInstance.ToolChangeFinished, mtsInstance.OperationComplete);
    connect(tmsInstance.FaultDetected, mdsInstance.AbnormalDetected);
    connect(clsInstance.SystemRunning, mtsInstance.ReadyForCommands);
    connect(clsInstance.FaultDetected, mdsInstance.AbnormalDetected);
    connect(mdsInstance.NormalMonitoring, mtsInstance.ReadyForCommands);
    connect(mdsInstance.AbnormalAlert, mtsInstance.SystemFault);
end;
